package main

import (
	"bufio"
	"os"
	"strings"
)

type Solution struct {
	inf *bufio.Reader
	ouf *bufio.Writer
}

func NewSolution() *Solution {
	return &Solution{
		inf: bufio.NewReader(os.Stdin),
		ouf: bufio.NewWriter(os.Stdout),
	}
}

func (s *Solution) readLine() string {
	line, _ := s.inf.ReadString('\n')
	return strings.TrimRight(line, "\r\n")
}

func (sol *Solution) solve() {
	s := sol.readLine()
	match := func(a, b string) bool {
		return a[0] == b[0] || a[1] == b[1]
	}
	found := false
	for _, it := range strings.Split(sol.readLine(), " ") {
		if match(s, it) {
			found = true
			break
		}
	}
	if found {
		sol.ouf.WriteString("YES\n")
	} else {
		sol.ouf.WriteString("NO\n")
	}
}

func (sol *Solution) Run() {
	//	for testNum := 1; testNum <= n; testNum++ {
	sol.solve()
	//	}

	sol.ouf.Flush()
}

func main() {
	done := make(chan struct{})
	go func() {
		NewSolution().Run()
		close(done)
	}()
	<-done
}
